package com.rescuefarm.ui.checkout;
import androidx.lifecycle.LiveData;import androidx.lifecycle.MutableLiveData;import androidx.lifecycle.ViewModel;
import com.rescuefarm.data.repository.CartRepository;import com.rescuefarm.data.repository.OrderRepository;
import com.rescuefarm.domain.enums.*;import com.rescuefarm.domain.model.*;import com.rescuefarm.service.order.*;
import java.util.*;
public class CheckoutViewModel extends ViewModel {private final CartRepository cartRepo;private final OrderRepository orderRepo;private final LiveData<Cart> cart;private final MutableLiveData<CheckoutState> state=new MutableLiveData<>(CheckoutState.idle());private final String requestId=UUID.randomUUID().toString();public CheckoutViewModel(CartRepository c,OrderRepository o){cartRepo=c;orderRepo=o;cart=c.observeCart();}public LiveData<Cart> getCart(){return cart;}public LiveData<CheckoutState> getState(){return state;}public boolean isGuest(){return cartRepo.getOwnerType()==CartOwnerType.GUEST;}public String getRequestId(){return requestId;}
public void submit(String name,String phone,String address,String latText,String lngText,FulfillmentType fulfillment,PaymentMethod payment,String note){Cart value=cart.getValue();List<CartItem> selected=new ArrayList<>();if(value!=null)for(CartItem i:value.getItems())if(i.isSelected())selected.add(i);try{CheckoutPolicy.requireSingleSeller(selected);double lat=parseCoordinate(latText),lng=parseCoordinate(lngText);if(clean(name).length()<2||clean(phone).length()<9)throw new IllegalArgumentException("Tên người nhận và số điện thoại chưa hợp lệ.");if(fulfillment==FulfillmentType.DELIVERY&&clean(address).isEmpty())throw new IllegalArgumentException("Delivery cần địa chỉ nhận hàng.");OrderOwnerType owner=cartRepo.getOwnerType()==CartOwnerType.GUEST?OrderOwnerType.GUEST:OrderOwnerType.CUSTOMER;CheckoutRequest req=new CheckoutRequest(requestId,owner,cartRepo.getOwnerKey(),name,phone,address,lat,lng,fulfillment,payment,note,selected);state.setValue(CheckoutState.loading());orderRepo.checkout(req,new OrderRepository.OrderCallback(){public void onSuccess(Order o,boolean replay){state.postValue(CheckoutState.success(o,replay));}public void onError(OrderRepository.ErrorCode e,String m){state.postValue(CheckoutState.error(m));}});}catch(IllegalArgumentException e){state.setValue(CheckoutState.error("MULTI_SELLER".equals(e.getMessage())?"Hãy checkout riêng từng seller.":e.getMessage()));}}
private double parseCoordinate(String v){if(clean(v).isEmpty())return 0D;double n=Double.parseDouble(clean(v));if(!Double.isFinite(n))throw new IllegalArgumentException("Tọa độ không hợp lệ.");return n;}private String clean(String v){return v==null?"":v.trim();}@Override protected void onCleared(){cartRepo.close();orderRepo.close();super.onCleared();}}
